//! Differential replay of the pinned `.gitignore` migrations.
//!
//! `tests/fixtures/migrations/gitignore_oracle.json` is generated by
//! `generate_migration_oracle.py` under the lock-exact development oracle
//! (`.venv-rust-oracle`, Python 3.11, `uv.lock`) at the pinned source baseline
//! `9aed3a8012cb5eb22c0128b14d525039f95fea7a`. Each case records the project
//! tree before the pinned migration, its `detect`/`can_apply`/`apply` verdicts,
//! the tree after, the git index contents and the post-apply `detect`.
//!
//! Two tests consume it:
//!
//! 1. [`replays_every_oracle_case_against_the_native_family`] rebuilds each
//!    before-tree, runs the **native** hooks, and requires the verdicts, the
//!    resulting bytes and the tracked-file set to match the oracle exactly.
//! 2. [`the_committed_fixture_is_reproducible_with_the_lock_exact_oracle`]
//!    regenerates the fixture with the verified oracle into a temporary
//!    directory and requires it to equal the committed bytes, so a drifted
//!    fixture or a drifted oracle fails loudly instead of passing on stale
//!    evidence.
//!
//! Every project, home, XDG directory and temp root is a fresh temporary
//! directory; nothing here touches the checkout's runtime state.

#[path = "../../sk-kernel/tests/support/oracle.rs"]
mod oracle;

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::process::Command;

use serde_json::Value;
use sk_install::{LedgerRecord, MigrationCatalog, NativeMigration};

const FIXTURE: &str = include_str!("fixtures/migrations/gitignore_oracle.json");
const LEDGER_FIXTURE: &str = include_str!("fixtures/migrations/ledger_oracle.json");
const SYMLINK_PREFIX: &str = "\u{0}symlink:";

fn native(id: &str) -> &'static NativeMigration {
    sk_install::NATIVE_MIGRATIONS
        .iter()
        .find(|migration| migration.id == id)
        .unwrap_or_else(|| panic!("{id} has no native implementation"))
}

fn write(path: &Path, content: &str) {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent).expect("create parent");
    }
    std::fs::write(path, content).expect("write");
}

/// Materialize a snapshot (`path -> bytes` plus explicit symlink entries).
fn materialize(root: &Path, files: &Value, tracked: &[String], want_git: bool) {
    let files = files.as_object().expect("files object");
    for (relative, content) in files {
        let content = content.as_str().expect("file text");
        if let Some(target) = content.strip_prefix(SYMLINK_PREFIX) {
            let path = root.join(relative);
            if let Some(parent) = path.parent() {
                std::fs::create_dir_all(parent).expect("create parent");
            }
            #[cfg(unix)]
            std::os::unix::fs::symlink(target, &path).expect("symlink");
            continue;
        }
        write(&root.join(relative), content);
    }
    if want_git {
        let git = |args: &[&str]| {
            let output = Command::new("git")
                .args(args)
                .current_dir(root)
                .env("GIT_CONFIG_NOSYSTEM", "1")
                .env("HOME", root.join(".git-home"))
                .output()
                .expect("git");
            assert!(
                output.status.success(),
                "git {args:?}: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        };
        git(&["init", "-q", "-b", "main"]);
        if !tracked.is_empty() {
            let mut add = vec!["add", "-f", "--"];
            add.extend(tracked.iter().map(String::as_str));
            git(&add);
        }
    }
}

fn snapshot(root: &Path) -> (BTreeMap<String, String>, Vec<String>) {
    let mut files = BTreeMap::new();
    let mut stack = vec![root.to_path_buf()];
    while let Some(directory) = stack.pop() {
        let Ok(entries) = std::fs::read_dir(&directory) else {
            continue;
        };
        for entry in entries.flatten() {
            let path = entry.path();
            let relative = path
                .strip_prefix(root)
                .expect("relative")
                .to_string_lossy()
                .replace('\\', "/");
            if relative == ".git"
                || relative.starts_with(".git/")
                || relative.starts_with(".git-home")
            {
                continue;
            }
            let metadata = std::fs::symlink_metadata(&path).expect("metadata");
            if metadata.file_type().is_symlink() {
                let target = std::fs::read_link(&path).expect("read link");
                files.insert(
                    relative,
                    format!("{SYMLINK_PREFIX}{}", target.to_string_lossy()),
                );
            } else if metadata.is_dir() {
                stack.push(path);
            } else {
                files.insert(
                    relative,
                    String::from_utf8(std::fs::read(&path).expect("read")).expect("utf8"),
                );
            }
        }
    }
    let mut tracked = Vec::new();
    if root.join(".git").is_dir() {
        let output = Command::new("git")
            .args(["ls-files", "--full-name"])
            .current_dir(root)
            .env("GIT_CONFIG_NOSYSTEM", "1")
            .env("HOME", root.join(".git-home"))
            .output()
            .expect("git ls-files");
        tracked = String::from_utf8(output.stdout)
            .expect("utf8")
            .lines()
            .map(str::to_string)
            .collect();
    }
    (files, tracked)
}

fn fixture() -> Value {
    serde_json::from_str(FIXTURE).expect("fixture parses")
}

fn baseline(value: &Value) -> String {
    value["baseline"].as_str().expect("baseline").to_string()
}

#[test]
fn the_fixture_is_bound_to_the_pinned_baseline() {
    assert_eq!(
        baseline(&fixture()),
        "9aed3a8012cb5eb22c0128b14d525039f95fea7a"
    );
    assert_eq!(
        fixture()["python"].as_str().expect("python version"),
        "3.11.15"
    );
    let ledger: Value = serde_json::from_str(LEDGER_FIXTURE).expect("ledger fixture");
    assert_eq!(
        baseline(&ledger),
        "9aed3a8012cb5eb22c0128b14d525039f95fea7a"
    );
}

#[test]
fn replays_every_oracle_case_against_the_native_family() {
    let fixture = fixture();
    let cases = fixture["cases"].as_array().expect("cases");
    assert!(cases.len() >= 61, "fixture unexpectedly small");
    let mut covered = std::collections::BTreeSet::new();
    for case in cases {
        let id = case["id"].as_str().expect("id");
        let name = case["case"].as_str().expect("case");
        covered.insert(id.to_string());
        let migration = native(id);
        let directory = tempfile::tempdir().expect("temp");
        let root = directory.path();
        let tracked: Vec<String> = case["before"]["tracked"]
            .as_array()
            .expect("tracked")
            .iter()
            .map(|value| value.as_str().expect("path").to_string())
            .collect();
        let want_git = case["before"]["git"].as_bool().unwrap_or(false);
        materialize(root, &case["before"]["files"], &tracked, want_git);
        let (before_files, before_tracked) = snapshot(root);
        let expected_before: BTreeMap<String, String> = case["before"]["files"]
            .as_object()
            .expect("files")
            .iter()
            .map(|(key, value)| (key.clone(), value.as_str().expect("text").to_string()))
            .collect();
        assert_eq!(before_files, expected_before, "{id}/{name} before");
        let mut expected_tracked = tracked.clone();
        expected_tracked.sort();
        let mut actual_tracked = before_tracked.clone();
        actual_tracked.sort();
        assert_eq!(actual_tracked, expected_tracked, "{id}/{name} index");

        let detected = (migration.detect)(root);
        match &case["detect"] {
            Value::Object(object) if object.contains_key("exception") => {
                assert!(
                    detected.is_err(),
                    "{id}/{name}: native detect accepted a project the oracle refused"
                );
            }
            value => {
                let expected = value["value"].as_bool().expect("detect bool");
                assert_eq!(
                    detected.expect("native detect"),
                    expected,
                    "{id}/{name}: detect diverged"
                );
            }
        }

        let can_apply = (migration.can_apply)(root);
        let expected_allowed = case["can_apply"]["value"][0].as_bool().expect("allowed");
        let expected_reason = case["can_apply"]["value"][1].as_str().expect("reason");
        match can_apply {
            Ok(None) => assert!(
                expected_allowed,
                "{id}/{name}: native allowed a refused project"
            ),
            Ok(Some(reason)) => {
                assert!(
                    !expected_allowed,
                    "{id}/{name}: native refused an allowed project"
                );
                if case["reason_comparable"].as_bool().unwrap_or(true)
                    && !expected_reason.is_empty()
                {
                    assert_eq!(
                        reason, expected_reason,
                        "{id}/{name}: refusal reason diverged"
                    );
                }
            }
            Err(error) => panic!("{id}/{name}: can_apply failed: {error}"),
        }

        if case["apply"].is_null() {
            // A case whose `can_apply` refuses a shape the runner never applies:
            // the fixture pins the refusal and the untouched tree only.
            let (after_files, _) = snapshot(root);
            assert_eq!(after_files, before_files, "{id}/{name}: tree mutated");
            continue;
        }
        let applied = (migration.apply)(root);
        let oracle_apply = &case["apply"];
        if oracle_apply["success"].as_bool().expect("success") {
            let expected_changes: Vec<String> = oracle_apply["changes"]
                .as_array()
                .expect("changes")
                .iter()
                .map(|value| value.as_str().expect("text").to_string())
                .collect();
            let expected_warnings: Vec<String> = oracle_apply["warnings"]
                .as_array()
                .expect("warnings")
                .iter()
                .map(|value| value.as_str().expect("text").to_string())
                .collect();
            let outcome = applied.unwrap_or_else(|error| {
                panic!("{id}/{name}: native apply failed: {error}");
            });
            let prefix = root.to_string_lossy().to_string();
            let normalized: Vec<String> = outcome
                .changes
                .iter()
                .map(|change| change.replace(&prefix, "<project>"))
                .collect();
            assert_eq!(normalized, expected_changes, "{id}/{name}: changes");
            assert_eq!(outcome.warnings, expected_warnings, "{id}/{name}: warnings");
        } else {
            assert!(
                applied.is_err(),
                "{id}/{name}: native apply succeeded where the oracle failed: {:?}",
                applied.map(|outcome| outcome.changes)
            );
        }

        let (after_files, after_tracked) = snapshot(root);
        let expected_after: BTreeMap<String, String> = case["after"]["files"]
            .as_object()
            .expect("files")
            .iter()
            .map(|(key, value)| (key.clone(), value.as_str().expect("text").to_string()))
            .collect();
        assert_eq!(after_files, expected_after, "{id}/{name}: after bytes");
        let mut expected_tracked: Vec<String> = case["after"]["tracked"]
            .as_array()
            .expect("tracked")
            .iter()
            .map(|value| value.as_str().expect("path").to_string())
            .collect();
        expected_tracked.sort();
        let mut actual_tracked = after_tracked;
        actual_tracked.sort();
        assert_eq!(actual_tracked, expected_tracked, "{id}/{name}: tracked set");

        let detected_after = (migration.detect)(root);
        match &case["detect_after"] {
            Value::Null => {}
            Value::Object(object) if object.contains_key("exception") => {
                assert!(detected_after.is_err(), "{id}/{name}: post-apply detect");
            }
            value => assert_eq!(
                detected_after.expect("detect"),
                value["value"].as_bool().expect("bool"),
                "{id}/{name}: post-apply detect diverged"
            ),
        }
    }
    // Every id the family claims is exercised by at least one oracle case.
    for required in [
        "0.4.8_gitignore_agents",
        "0.12.1_remove_kitty_specs_from_gitignore",
        "2.0.0a5_remove_wp_status_gitignore_rule",
        "2.0.9_state_gitignore",
        "3.2.0rc35_kittify_runtime_git_hygiene",
        "3.2.3_encoding_provenance_gitignore_backfill",
        "3.2.4_derived_mission_views_gitignore_backfill",
        "3.2.4_runtime_dirs_gitignore_backfill",
        "3.2.6rc3_lint_report_gitignore_backfill",
        "3.2.6rc3_worktrees_gitignore_backfill",
        "0.9.0_frontmatter_only_lanes",
        "0.10.12_charter_cleanup",
        "3.2.5_agents_skills_gitignore_backfill",
        "normalize_activation_absence",
        "unify_charter_activation_promote_answers",
        "0.2.0_specify_to_kittify",
        "0.8.0_remove_active_mission",
        "0.10.9_repair_templates",
        "2.0.0_historical_status_migration",
    ] {
        assert!(covered.contains(required), "{required} has no oracle case");
    }
}

#[test]
fn replay_ledger_lines_match_the_oracle_wire_shape() {
    let fixture: Value = serde_json::from_str(LEDGER_FIXTURE).expect("ledger fixture");
    let catalog = MigrationCatalog::embedded().expect("catalog");
    let applied_at = fixture["applied_at"].as_str().expect("applied_at");
    let cli_version = fixture["cli_version"].as_str().expect("cli_version");
    let records = fixture["records"].as_object().expect("records");
    let mut compared = 0;
    for (id, results) in records {
        let Some(spec) = catalog.get(id) else {
            continue;
        };
        // Only the ids this tranche executes natively; the rest are evidence
        // for the ledger shape the coordinator's remaining families must match.
        let native = sk_install::NATIVE_MIGRATIONS
            .iter()
            .any(|migration| migration.id == id);
        for (result, line) in results.as_object().expect("results") {
            let mut record = LedgerRecord::for_spec(spec, result, cli_version);
            record.applied_at = applied_at.to_string();
            record.superseded_by = spec.superseded_by.clone();
            let expected = line.as_str().expect("line");
            assert_eq!(record.to_line(), expected, "{id}/{result}");
            if native {
                compared += 1;
            }
        }
    }
    assert!(
        compared >= 42 * 3,
        "the ledger oracle covered only {compared} native id/result rows"
    );
}

/// The generator this fixture comes from, resolved from the crate root.
fn generator() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/migrations/generate_migration_oracle.py")
}

fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

#[test]
fn the_committed_fixture_is_reproducible_with_the_lock_exact_oracle() {
    let python = oracle::python();
    let root = repo_root();
    let output = tempfile::tempdir().expect("temp");
    let sandbox = tempfile::tempdir().expect("temp");
    let result = Command::new(&python)
        .arg(generator())
        .arg("--out")
        .arg(output.path())
        .current_dir(&root)
        .env("PYTHONPATH", root.join("src"))
        .env("SPEC_KITTY_PACKS_ROOT", root.join("packs"))
        .env("HOME", sandbox.path().join("home"))
        .env("USERPROFILE", sandbox.path().join("home"))
        .env("XDG_CONFIG_HOME", sandbox.path().join("config"))
        .env("XDG_CACHE_HOME", sandbox.path().join("cache"))
        .env("TMPDIR", sandbox.path())
        .env("PYTHONDONTWRITEBYTECODE", "1")
        .output()
        .expect("run generator");
    assert!(
        result.status.success(),
        "generator failed: {}",
        String::from_utf8_lossy(&result.stderr)
    );
    for name in ["gitignore_oracle.json", "ledger_oracle.json"] {
        let committed: Value = serde_json::from_str(match name {
            "gitignore_oracle.json" => FIXTURE,
            _ => LEDGER_FIXTURE,
        })
        .expect("committed");
        let regenerated: Value =
            serde_json::from_str(&std::fs::read_to_string(output.path().join(name)).expect("read"))
                .expect("regenerated");
        assert_eq!(
            regenerated, committed,
            "{name} drifted; regenerate it with the documented command"
        );
    }
}

#[test]
fn the_family_does_not_claim_unported_ids() {
    // Ids this family must not reach: only a real port (with its own Source-first
    // tests) may remove one from this list. `4.0.0rc8_backfill_migration_ledger`
    // left it when `migrations::ledger_adoption` landed.
    for unported in [
        "0.6.5_commands_rename",
        "charter_pack_cutover",
        "3.2.0rc35_charter_bundle_v2",
    ] {
        assert!(
            !sk_install::NATIVE_MIGRATIONS
                .iter()
                .any(|migration| migration.id == unported),
            "{unported} must stay unimplemented"
        );
    }
}
